(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(y * 0.018 + t * 0.25) * 12 + Math.cos(x * 0.012 - t * 0.18) * 8;
  const w1y = Math.cos(x * 0.02 - t * 0.22) * 12 + Math.sin(y * 0.015 + t * 0.3) * 8;
  const nx = x + w1x, ny = y + w1y;
  const w2x = Math.sin(ny * 0.025 + t * 0.15) * 6 + Math.cos(nx * 0.03 - t * 0.2) * 5;
  const w2y = Math.cos(nx * 0.022 - t * 0.18) * 6 + Math.sin(ny * 0.028 + t * 0.25) * 5;
  const sx = nx + w2x, sy = ny + w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 0.7],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.85],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 0.6],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.9],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 0.5],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.75],
    [80+Math.sin(t*0.45+3)*60, 40+Math.cos(t*0.65+1)*40, 0.11, 2.1, 0.65],
    [400+Math.cos(t*0.55+2)*70, 200+Math.sin(t*0.75+4)*50, 0.085, 1.8, 0.8]
  ];
  let aS = 0, iS = 0, diff = 0;
  for (const [sX, sY, f, sp, amp] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    aS += Math.sin(d*f - t*sp) * amp;
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5) * amp;
    diff += Math.cos(d*f*1.3 - t*sp*0.8 + 2.0) * amp * 0.5;
  }
  const act = aS/6.5, inh = iS/6.5, diffusion = diff/6.5;
  const bg1 = (Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2;
  const bg2 = Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2;
  const bg3 = Math.sin(sx*0.08+t*0.5)*Math.sin(sy*0.06-t*0.4)*0.3;
  const bg4 = Math.sin(Math.sqrt(sx*sx+sy*sy)*0.03-t*0.6)*0.25;
  const bg = bg1+bg2+bg3+bg4;
  const dist = Math.sqrt((sx-cx)**2+(sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const sp1 = (Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.3;
  const sp2 = Math.sin(dist*0.08+ang*2-t*2.0)*0.15;
  const sp3 = Math.sin(dist*0.03-ang*5+t*0.8)*0.1;
  const spiral = sp1+sp2+sp3;
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const cell2 = Math.tanh((Math.cos(sx*0.2-sy*0.1+t*0.7)*Math.sin(sy*0.18+sx*0.05-t*0.5))*1.2)*0.2;
  const raw = act-inh*0.7+bg*0.3+spiral+diffusion*0.4+cell+cell2;
  const reaction = Math.tanh(raw*1.8);
  const glow = Math.max(0, reaction)**2*0.4;
  const blend = reaction*0.65+cell*0.15+cell2*0.1+glow*0.1;
  const v = blend*0.5+0.5;
  const pal = [
    [5,12,48],[10,40,85],[15,75,115],[20,120,130],[50,160,120],
    [140,190,90],[220,190,60],[240,150,60],[230,100,65],[200,65,75],
    [150,40,80],[90,25,70],[45,15,55],[5,12,48]
  ];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const lum = 0.85+Math.sin(reaction*Math.PI)*0.15;
  const edge = Math.abs(reaction)>0.65?1.08+Math.abs(reaction)*0.07:1.0;
  const bright = lum*edge;
  return [
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*bright)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*bright)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*bright)|0
  ];
}
